$path = 'J:\REACT NATIVE APPS\DeenIslam\app\src\screens\AqidahLifeScreen.tsx'
$s = [IO.File]::ReadAllText($path)
$old = "  const lifestyleChapters:any[] = remoteChapters?.length ? remoteChapters.map((item,index)=>({...item,number:String(item.order||index+1).padStart(2,'0'),text:(item.introduction||[]).join(' '),points:item.lessons||[],category:item.category||'Islamic Lifestyle'})) : [...MUSLIM_LIFE_CHAPTERS];"
$new = "  const managedCategories = (remoteChapters??[]).filter(item=>item.kind==='category').map((item):Topic=>({id:item.slug,icon:item.icon||'◆',title:item.title,subtitle:item.subtitle||'',intro:(item.introduction||[]).join(' ')||item.subtitle||'',principles:item.lessons||[]}));`r`n  const generalManaged = managedCategories.filter(item => (remoteChapters??[]).find(raw=>raw.slug===item.id)?.section !== 'Islamic Educator Life');`r`n  const educatorManaged = managedCategories.filter(item => (remoteChapters??[]).find(raw=>raw.slug===item.id)?.section === 'Islamic Educator Life');`r`n  const managedChapterItems = (remoteChapters??[]).filter(item=>item.kind==='chapter'&&item.parentCategorySlug===selected?.id);`r`n  const lifestyleChapters:any[] = managedChapterItems.length ? managedChapterItems.map((item,index)=>({...item,number:String(item.order||index+1).padStart(2,'0'),text:(item.introduction||[]).join(' '),points:item.lessons||[],category:item.section||'Islamic Lifestyle'})) : selected?.id==='muslim-life' ? [...MUSLIM_LIFE_CHAPTERS] : [];"
if (-not $s.Contains($old)) { throw 'Lifestyle chapter calculation not found' }
$s = $s.Replace($old, $new)
$s = $s.Replace('<TopicSection title="GENERAL MUSLIM LIFE" topics={GENERAL_TOPICS} onOpen={setSelected}/>', '<TopicSection title="GENERAL MUSLIM LIFE" topics={managedCategories.length ? generalManaged : GENERAL_TOPICS} onOpen={setSelected}/>')
$s = $s.Replace('<TopicSection title="ISLAMIC EDUCATOR LIFE" topics={EDUCATOR_TOPICS} onOpen={setSelected}/>', '<TopicSection title="ISLAMIC EDUCATOR LIFE" topics={managedCategories.length ? educatorManaged : EDUCATOR_TOPICS} onOpen={setSelected}/>')
[IO.File]::WriteAllText($path, $s, (New-Object Text.UTF8Encoding($false)))
